-- AMANA : mise a jour des templates de notification (email/sms/push) en francais
-- Genere le 2026-07-30. A executer sur la base de production existante (phpMyAdmin ou client MySQL).
-- Ne touche que les colonnes de contenu, aucune modification de structure/schema.

-- 1) Template email global (layout maitre avec logo texte "AMANA" en attendant le vrai fichier logo)
UPDATE `general_settings` SET
  `email_template` = '<!DOCTYPE html>\n<html lang="fr">\n\n<head>\n    <meta charset="UTF-8">\n    <meta http-equiv="X-UA-Compatible" content="IE=edge">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>{{site_name}}</title>\n    <style>\n        body {\n            margin: 0;\n            padding: 0;\n            font-family: \'Segoe UI\', Arial, sans-serif;\n            background-color: #F1F5F9;\n            -webkit-text-size-adjust: 100%;\n            -ms-text-size-adjust: 100%;\n        }\n\n        table {\n            border-spacing: 0;\n            border-collapse: collapse;\n            width: 100%;\n        }\n\n        img {\n            display: block;\n            border: 0;\n            line-height: 0;\n        }\n\n        a {\n            color: #2B5BEE;\n            text-decoration: none;\n        }\n\n        .email-wrapper {\n            width: 100%;\n            background-color: #F1F5F9;\n            padding: 32px 0;\n        }\n\n        .email-container {\n            width: 100%;\n            max-width: 600px;\n            margin: 0 auto;\n            background-color: #FFFFFF;\n            border-radius: 16px;\n            overflow: hidden;\n            box-shadow: 0 4px 24px rgba(23, 53, 131, 0.12);\n        }\n\n        .email-topbar {\n            height: 6px;\n            background: linear-gradient(90deg, #2B5BEE 0%, #173583 100%);\n        }\n\n        .email-logo {\n            text-align: center;\n            padding: 32px 24px 24px 24px;\n            background-color: #FFFFFF;\n        }\n\n        .email-logo img {\n            max-width: 220px;\n            width: 100%;\n            margin: 0 auto;\n        }\n\n        .email-logo .brand-text {\n            display: inline-block;\n            font-size: 24px;\n            font-weight: 700;\n            color: #173583;\n            letter-spacing: 1px;\n        }\n\n        .email-logo .brand-text .dot {\n            color: #2B5BEE;\n        }\n\n        .email-content {\n            padding: 8px 36px 32px 36px;\n            text-align: left;\n        }\n\n        .email-content h1 {\n            font-size: 20px;\n            color: #1E293B;\n            font-weight: 700;\n            margin: 0 0 18px 0;\n        }\n\n        .msg-body p {\n            font-size: 15px;\n            color: #475569;\n            line-height: 1.7;\n            margin: 0 0 14px 0;\n        }\n\n        .msg-body ul {\n            font-size: 15px;\n            color: #475569;\n            line-height: 1.7;\n            margin: 0 0 14px 0;\n            padding-left: 20px;\n        }\n\n        .msg-body li {\n            margin-bottom: 6px;\n        }\n\n        .msg-body strong {\n            color: #1E293B;\n        }\n\n        .email-divider {\n            margin: 24px 0;\n            border: none;\n            border-top: 1px solid #E2E8F0;\n        }\n\n        .email-note {\n            font-size: 13px;\n            color: #94A3B8;\n            margin: 0;\n            line-height: 1.6;\n        }\n\n        .email-footer {\n            background-color: #173583;\n            color: #C7D2FE;\n            text-align: center;\n            font-size: 13px;\n            padding: 26px 24px;\n        }\n\n        .email-footer .tagline {\n            color: #FFFFFF;\n            font-size: 15px;\n            font-weight: 700;\n            margin-bottom: 6px;\n        }\n\n        .email-footer a {\n            color: #FFFFFF;\n            font-weight: 600;\n        }\n\n        @media only screen and (max-width: 480px) {\n            .email-content {\n                padding: 8px 20px 28px 20px;\n            }\n\n            .email-logo {\n                padding: 24px 20px 16px 20px;\n            }\n        }\n    </style>\n</head>\n\n<body>\n    <div class="email-wrapper">\n        <table class="email-container" cellpadding="0" cellspacing="0">\n            <tbody>\n                <tr>\n                    <td>\n                        <div class="email-topbar"></div>\n                        <div class="email-logo">\n                            <img src="data:image/png;base64," alt="{{site_name}} - Transfert d\'argent" width="220">\n                        </div>\n                        <div class="email-content">\n                            <h1>Bonjour {{fullname}},</h1>\n                            <div class="msg-body">{{message}}</div>\n                            <hr class="email-divider">\n                            <p class="email-note">Cet e-mail vous a été envoyé automatiquement par {{site_name}}. Pour toute question, contactez notre équipe support depuis l\'application.</p>\n                        </div>\n                        <div class="email-footer">\n                            <div class="tagline">{{site_name}} &mdash; Transfert d\'argent</div>\n                            &copy; {{site_name}}. Tous droits r&eacute;serv&eacute;s.\n                        </div>\n                    </td>\n                </tr>\n            </tbody>\n        </table>\n    </div>\n</body>\n\n</html>',
  `sms_template` = 'Bonjour {{fullname}}, {{message}} - {{site_name}}',
  `push_template` = '{{message}}',
  `push_title` = '{{site_name}}'
WHERE `id` = 1;

-- 2) Templates par evenement (48 lignes, DEFAULT non touche car pur passe-plat)
UPDATE `notification_templates` SET
  `subject` = 'Votre compte {{site_name}} a été crédité',
  `push_title` = 'Compte crédité',
  `email_body` = '<p>Nous vous informons qu\'un montant de <strong>{{amount}} {{site_currency}}</strong> a été ajouté à votre compte.</p><p>Détails de l\'opération :</p><ul><li><strong>Numéro de transaction :</strong> {{trx}}</li><li><strong>Solde actuel :</strong> {{post_balance}} {{site_currency}}</li><li><strong>Motif :</strong> {{remark}}</li></ul><p>Pour toute question, notre équipe support reste à votre disposition.</p>',
  `sms_body` = 'Un montant de {{amount}} {{site_currency}} a été ajouté à votre compte {{site_name}}. Solde : {{post_balance}} {{site_currency}}.',
  `push_body` = '{{amount}} {{site_currency}} ont été ajoutés à votre compte.'
WHERE `act` = 'BAL_ADD';

UPDATE `notification_templates` SET
  `subject` = 'Votre compte {{site_name}} a été débité',
  `push_title` = 'Compte débité',
  `email_body` = '<p>Nous vous informons qu\'un montant de <strong>{{amount}} {{site_currency}}</strong> a été retiré de votre compte.</p><p>Détails de l\'opération :</p><ul><li><strong>Numéro de transaction :</strong> {{trx}}</li><li><strong>Solde actuel :</strong> {{post_balance}} {{site_currency}}</li><li><strong>Motif :</strong> {{remark}}</li></ul><p>Pour toute question, notre équipe support reste à votre disposition. Merci de votre confiance en {{site_name}}.</p>',
  `sms_body` = 'Un montant de {{amount}} {{site_currency}} a été débité de votre compte {{site_name}}. Solde : {{post_balance}} {{site_currency}}.',
  `push_body` = '{{amount}} {{site_currency}} ont été débités de votre compte.'
WHERE `act` = 'BAL_SUB';

UPDATE `notification_templates` SET
  `subject` = 'Votre dépôt a été effectué avec succès',
  `push_title` = 'Dépôt réussi',
  `email_body` = '<p>Votre dépôt de <strong>{{amount}} {{site_currency}}</strong> via <strong>{{method_name}}</strong> a été effectué avec succès.</p><p>Détails du dépôt :</p><ul><li><strong>Montant :</strong> {{amount}} {{site_currency}}</li><li><strong>Frais :</strong> {{charge}} {{site_currency}}</li><li><strong>Taux de conversion :</strong> 1 {{site_currency}} = {{rate}} {{method_currency}}</li><li><strong>Montant reçu :</strong> {{method_amount}} {{method_currency}}</li><li><strong>Méthode :</strong> {{method_name}}</li><li><strong>Numéro de transaction :</strong> {{trx}}</li></ul><p>Votre solde actuel est de <strong>{{post_balance}} {{site_currency}}</strong>.</p><p>Merci de votre confiance.</p>',
  `sms_body` = 'Votre dépôt de {{amount}} {{site_currency}} via {{method_name}} est confirmé. Solde : {{post_balance}} {{site_currency}}. Réf : {{trx}}.',
  `push_body` = 'Votre dépôt de {{amount}} {{site_currency}} a été crédité avec succès.'
WHERE `act` = 'DEPOSIT_COMPLETE';

UPDATE `notification_templates` SET
  `subject` = 'Votre demande de dépôt a été approuvée',
  `push_title` = 'Dépôt approuvé',
  `email_body` = '<p>Votre demande de dépôt de <strong>{{amount}} {{site_currency}}</strong> via <strong>{{method_name}}</strong> a été <strong>approuvée</strong>.</p><p>Détails du dépôt :</p><ul><li><strong>Montant :</strong> {{amount}} {{site_currency}}</li><li><strong>Frais :</strong> {{charge}} {{site_currency}}</li><li><strong>Taux de conversion :</strong> 1 {{site_currency}} = {{rate}} {{method_currency}}</li><li><strong>Montant reçu :</strong> {{method_amount}} {{method_currency}}</li><li><strong>Méthode :</strong> {{method_name}}</li><li><strong>Numéro de transaction :</strong> {{trx}}</li></ul><p>Votre solde actuel est de <strong>{{post_balance}} {{site_currency}}</strong>.</p><p>Pour toute question, notre équipe support est à votre écoute.</p>',
  `sms_body` = 'Votre demande de dépôt de {{amount}} {{site_currency}} via {{method_name}} a été approuvée. Solde : {{post_balance}} {{site_currency}}.',
  `push_body` = 'Votre dépôt de {{amount}} {{site_currency}} via {{method_name}} a été approuvé.'
WHERE `act` = 'DEPOSIT_APPROVE';

UPDATE `notification_templates` SET
  `subject` = 'Votre demande de dépôt n\'a pas été approuvée',
  `push_title` = 'Dépôt refusé',
  `email_body` = '<p>Nous sommes au regret de vous informer que votre demande de dépôt de <strong>{{amount}} {{site_currency}}</strong> via <strong>{{method_name}}</strong> n\'a pas été approuvée.</p><p>Détails :</p><ul><li><strong>Taux de conversion :</strong> 1 {{site_currency}} = {{rate}} {{method_currency}}</li><li><strong>Montant :</strong> {{method_amount}} {{method_currency}}</li><li><strong>Méthode :</strong> {{method_name}}</li><li><strong>Frais :</strong> {{charge}}</li><li><strong>Numéro de transaction :</strong> {{trx}}</li></ul><p><strong>Motif du refus :</strong> {{rejection_message}}</p><p>Aucun montant n\'a été débité de votre compte. Pour toute question, contactez notre support.</p>',
  `sms_body` = 'Votre demande de dépôt de {{amount}} {{site_currency}} via {{method_name}} a été refusée. Motif : {{rejection_message}}.',
  `push_body` = 'Votre demande de dépôt de {{amount}} {{site_currency}} via {{method_name}} a été refusée.'
WHERE `act` = 'DEPOSIT_REJECT';

UPDATE `notification_templates` SET
  `subject` = 'Votre demande de dépôt a bien été enregistrée',
  `push_title` = 'Dépôt en cours de traitement',
  `email_body` = '<p>Nous confirmons la bonne réception de votre demande de dépôt de <strong>{{amount}} {{site_currency}}</strong> via <strong>{{method_name}}</strong>.</p><p>Détails :</p><ul><li><strong>Montant :</strong> {{amount}} {{site_currency}}</li><li><strong>Frais :</strong> {{charge}} {{site_currency}}</li><li><strong>Taux de conversion :</strong> 1 {{site_currency}} = {{rate}} {{method_currency}}</li><li><strong>Montant à régler :</strong> {{method_amount}} {{method_currency}}</li><li><strong>Méthode :</strong> {{method_name}}</li><li><strong>Numéro de transaction :</strong> {{trx}}</li></ul><p>Vous serez notifié dès que votre dépôt aura été traité par notre équipe.</p>',
  `sms_body` = 'Votre demande de dépôt de {{amount}} {{site_currency}} via {{method_name}} a été reçue et est en cours de traitement.',
  `push_body` = 'Votre demande de dépôt de {{amount}} {{site_currency}} via {{method_name}} a bien été soumise.'
WHERE `act` = 'DEPOSIT_REQUEST';

UPDATE `notification_templates` SET
  `subject` = 'Code de réinitialisation de votre code PIN',
  `push_title` = 'Code de réinitialisation',
  `email_body` = '<p>Vous avez demandé la réinitialisation du code PIN de votre compte le <strong>{{time}}</strong>.</p><p style="text-align:center;font-size:30px;font-weight:700;color:#173583;letter-spacing:6px;margin:24px 0;">{{code}}</p><p>Cette demande provient de :</p><ul><li><strong>Adresse IP :</strong> {{ip}}</li><li><strong>Navigateur :</strong> {{browser}}</li><li><strong>Système :</strong> {{operating_system}}</li></ul><p><strong>Ne communiquez ce code à personne.</strong> Si vous n\'êtes pas à l\'origine de cette demande, ignorez ce message ou contactez immédiatement notre support.</p>',
  `sms_body` = '{{code}} est votre code de réinitialisation {{site_name}}. Ne le partagez avec personne.',
  `push_body` = 'Votre code de réinitialisation du PIN : {{code}}.'
WHERE `act` = 'PASS_RESET_CODE';

UPDATE `notification_templates` SET
  `subject` = 'Votre code PIN a été réinitialisé',
  `push_title` = 'PIN réinitialisé',
  `email_body` = '<p>Votre code PIN a été réinitialisé avec succès le <strong>{{time}}</strong>.</p><ul><li><strong>Adresse IP :</strong> {{ip}}</li><li><strong>Navigateur :</strong> {{browser}}</li><li><strong>Système :</strong> {{operating_system}}</li></ul><p>Si vous n\'êtes pas à l\'origine de cette modification, contactez immédiatement notre support afin de sécuriser votre compte.</p>',
  `sms_body` = 'Votre code PIN {{site_name}} a été réinitialisé avec succès. Ce n\'est pas vous ? Contactez le support.',
  `push_body` = 'Votre code PIN a été réinitialisé avec succès.'
WHERE `act` = 'PASS_RESET_DONE';

UPDATE `notification_templates` SET
  `subject` = 'Réponse à votre ticket #{{ticket_id}}',
  `push_title` = 'Réponse du support',
  `email_body` = '<p>Notre équipe support a répondu à votre ticket <strong>« {{ticket_subject}} »</strong> (réf. #{{ticket_id}}) :</p><p style="background:#F1F5F9;border-radius:10px;padding:16px;color:#1E293B;">{{reply}}</p><p>Vous pouvez consulter l\'intégralité de la conversation et répondre directement depuis votre espace : <a href="{{link}}" target="_blank">Voir le ticket</a>.</p><p>Merci de votre patience.</p>',
  `sms_body` = 'Notre support a répondu à votre ticket "{{ticket_subject}}" (#{{ticket_id}}) sur {{site_name}}.',
  `push_body` = 'Notre équipe a répondu à votre ticket « {{ticket_subject}} ».'
WHERE `act` = 'ADMIN_SUPPORT_REPLY';

UPDATE `notification_templates` SET
  `subject` = 'Votre code de vérification e-mail {{site_name}}',
  `push_title` = 'Vérification e-mail',
  `email_body` = '<p>Merci de confirmer votre adresse e-mail à l\'aide du code ci-dessous :</p><p style="text-align:center;font-size:30px;font-weight:700;color:#173583;letter-spacing:6px;margin:24px 0;">{{code}}</p><p>Saisissez ce code dans l\'application pour finaliser la vérification.</p><p><strong>Ne communiquez ce code à personne.</strong> Si vous n\'êtes pas à l\'origine de cette demande, ignorez simplement ce message.</p>',
  `sms_body` = '{{code}} est votre code de vérification e-mail {{site_name}}.',
  `push_body` = 'Votre code de vérification e-mail : {{code}}.'
WHERE `act` = 'EVER_CODE';

UPDATE `notification_templates` SET
  `subject` = 'Votre code de vérification par SMS',
  `push_title` = 'Code de vérification',
  `email_body` = '<p>Voici votre code de vérification par SMS :</p><p style="text-align:center;font-size:30px;font-weight:700;color:#173583;letter-spacing:6px;margin:24px 0;">{{code}}</p><p><strong>Ne communiquez jamais ce code.</strong> Si vous n\'êtes pas à l\'origine de cette demande, ignorez ce message.</p>',
  `sms_body` = 'Votre code de vérification est {{code}}. Ne le partagez avec personne.',
  `push_body` = 'Votre code de vérification : {{code}}.'
WHERE `act` = 'SVER_CODE';

UPDATE `notification_templates` SET
  `subject` = 'Votre retrait a été traité avec succès',
  `push_title` = 'Retrait approuvé',
  `email_body` = '<p>Votre demande de retrait de <strong>{{amount}} {{site_currency}}</strong> via <strong>{{method_name}}</strong> a été traitée avec succès.</p><p>Détails du retrait :</p><ul><li><strong>Montant :</strong> {{amount}} {{site_currency}}</li><li><strong>Frais :</strong> {{charge}} {{site_currency}}</li><li><strong>Taux de conversion :</strong> 1 {{site_currency}} = {{rate}} {{method_currency}}</li><li><strong>Montant reçu :</strong> {{method_amount}} {{method_currency}}</li><li><strong>Méthode :</strong> {{method_name}}</li><li><strong>Numéro de transaction :</strong> {{trx}}</li></ul><p><strong>Détails du paiement :</strong> {{admin_details}}</p>',
  `sms_body` = 'Votre retrait de {{amount}} {{site_currency}} via {{method_name}} a été traité avec succès. Réf : {{trx}}.',
  `push_body` = 'Votre retrait de {{amount}} {{site_currency}} a été traité avec succès.'
WHERE `act` = 'WITHDRAW_APPROVE';

UPDATE `notification_templates` SET
  `subject` = 'Votre demande de retrait a été refusée',
  `push_title` = 'Retrait refusé',
  `email_body` = '<p>Nous sommes au regret de vous informer que votre demande de retrait de <strong>{{amount}} {{site_currency}}</strong> via <strong>{{method_name}}</strong> a été refusée.</p><p>Détails :</p><ul><li><strong>Montant :</strong> {{amount}} {{site_currency}}</li><li><strong>Frais :</strong> {{charge}} {{site_currency}}</li><li><strong>Montant attendu :</strong> {{method_amount}} {{method_currency}}</li><li><strong>Méthode :</strong> {{method_name}}</li><li><strong>Numéro de transaction :</strong> {{trx}}</li></ul><p><strong>Remboursement :</strong> {{amount}} {{site_currency}} ont été recrédités sur votre compte. Solde actuel : <strong>{{post_balance}} {{site_currency}}</strong>.</p><p><strong>Motif du refus :</strong> {{admin_details}}</p>',
  `sms_body` = 'Votre retrait de {{amount}} {{site_currency}} a été refusé et remboursé. Solde : {{post_balance}} {{site_currency}}.',
  `push_body` = 'Votre demande de retrait de {{amount}} {{site_currency}} a été refusée et remboursée.'
WHERE `act` = 'WITHDRAW_REJECT';

UPDATE `notification_templates` SET
  `subject` = 'Votre demande de retrait a bien été enregistrée',
  `push_title` = 'Retrait en cours',
  `email_body` = '<p>Nous confirmons la bonne réception de votre demande de retrait de <strong>{{amount}} {{site_currency}}</strong> via <strong>{{method_name}}</strong>.</p><p>Détails :</p><ul><li><strong>Montant :</strong> {{amount}} {{site_currency}}</li><li><strong>Frais :</strong> {{charge}} {{site_currency}}</li><li><strong>Montant attendu :</strong> {{method_amount}} {{method_currency}}</li><li><strong>Méthode :</strong> {{method_name}}</li><li><strong>Numéro de transaction :</strong> {{trx}}</li></ul><p>Votre solde actuel est de <strong>{{post_balance}} {{site_currency}}</strong>. Vous serez notifié dès que votre retrait sera traité.</p>',
  `sms_body` = 'Votre demande de retrait de {{amount}} {{site_currency}} est en cours de traitement. Réf : {{trx}}.',
  `push_body` = 'Votre demande de retrait de {{amount}} {{site_currency}} a bien été soumise.'
WHERE `act` = 'WITHDRAW_REQUEST';

UPDATE `notification_templates` SET
  `subject` = 'Votre vérification d\'identité (KYC) a été approuvée',
  `push_title` = '{{site_name}} - KYC approuvée',
  `email_body` = '<p>Nous avons le plaisir de vous informer que votre vérification d\'identité (KYC) a été examinée et <strong>approuvée</strong>. Vous pouvez désormais effectuer toutes les opérations de retrait sur la plateforme.</p><p>Nous vous remercions d\'avoir complété cette étape rapidement : elle nous permet de garantir la sécurité de {{site_name}} pour l\'ensemble de nos utilisateurs.</p><p>Pour toute question, notre équipe support reste à votre entière disposition.</p><p>Merci de votre confiance en {{site_name}}.</p>',
  `sms_body` = 'Votre vérification d\'identité (KYC) a été approuvée. Vous pouvez désormais effectuer tous vos retraits sur {{site_name}}.',
  `push_body` = 'Votre vérification d\'identité (KYC) a été approuvée avec succès.'
WHERE `act` = 'KYC_APPROVE';

UPDATE `notification_templates` SET
  `subject` = 'Votre vérification d\'identité (KYC) n\'a pas été approuvée',
  `push_title` = '{{site_name}} - KYC refusée',
  `email_body` = '<p>Nous sommes au regret de vous informer que les documents fournis pour votre vérification d\'identité (KYC) n\'ont pas répondu à nos critères de validation.</p><p>Cela peut être dû à des informations incomplètes ou incohérentes dans les documents transmis. Nous vous invitons à vérifier vos informations et à soumettre à nouveau votre dossier une fois les corrections apportées.</p><p><strong>Motif du refus :</strong> {{reason}}</p><p>Si vous souhaitez des précisions, notre équipe support se tient à votre disposition.</p>',
  `sms_body` = 'Votre vérification d\'identité (KYC) n\'a pas été approuvée. Motif : {{reason}}. Vous pouvez soumettre à nouveau votre dossier.',
  `push_body` = 'Votre vérification d\'identité (KYC) n\'a pas été approuvée.'
WHERE `act` = 'KYC_REJECT';

UPDATE `notification_templates` SET
  `subject` = 'Commission de cash-in reçue',
  `push_title` = 'Commission cash-in',
  `email_body` = '<p>Vous avez reçu une commission de <strong>{{currency_symbol}}{{commission}}</strong> pour une opération de cash-in.</p><p>Détails :</p><ul><li><strong>Numéro de transaction :</strong> {{trx}}</li><li><strong>Nouveau solde :</strong> {{balance}}</li><li><strong>Date et heure :</strong> {{time}}</li></ul><p>Merci pour votre engagement continu. Pour toute question, notre équipe support est à votre disposition.</p>',
  `sms_body` = 'Vous avez reçu une commission de {{currency_symbol}}{{commission}} pour un cash-in. Solde : {{balance}}. {{site_name}}',
  `push_body` = 'Vous avez reçu une commission de {{currency_symbol}}{{commission}} pour une opération de cash-in.'
WHERE `act` = 'CASH_IN_COMMISSION_AGENT';

UPDATE `notification_templates` SET
  `subject` = 'Confirmation de votre cash-in',
  `push_title` = 'Nouveau cash-in',
  `email_body` = '<p>Nous avons le plaisir de vous confirmer qu\'un cash-in de <strong>{{amount}}</strong> effectué par <strong>{{agent}}</strong> a été réalisé avec succès.</p><p>Détails de l\'opération :</p><ul><li><strong>Numéro de transaction :</strong> {{trx}}</li><li><strong>Nouveau solde :</strong> {{balance}}</li><li><strong>Date et heure :</strong> {{time}}</li></ul><p>Pour toute question, notre équipe support reste à votre disposition. Merci de votre confiance.</p>',
  `sms_body` = 'Cash-in de {{amount}} effectué par {{agent}} confirmé. Solde : {{balance}}. {{site_name}}',
  `push_body` = 'Un cash-in de {{amount}} effectué par {{agent}} a été réalisé avec succès.'
WHERE `act` = 'CASH_IN';

UPDATE `notification_templates` SET
  `subject` = 'Cash-in effectué avec succès',
  `push_title` = 'Nouveau cash-in',
  `email_body` = '<p>Vous avez effectué avec succès un cash-in de <strong>{{amount}}</strong> vers <strong>{{user}}</strong>.</p><p>Détails de l\'opération :</p><ul><li><strong>Numéro de transaction :</strong> {{trx}}</li><li><strong>Solde restant :</strong> {{balance}}</li><li><strong>Date et heure :</strong> {{time}}</li></ul><p>Merci pour votre engagement continu. Pour toute question, contactez notre support.</p>',
  `sms_body` = 'Cash-in de {{amount}} vers {{user}} effectué avec succès. Solde : {{balance}}. {{site_name}}',
  `push_body` = 'Vous avez effectué un cash-in de {{amount}} vers {{user}} avec succès.'
WHERE `act` = 'CASH_IN_AGENT';

UPDATE `notification_templates` SET
  `subject` = 'Votre transfert d\'argent a été effectué',
  `push_title` = 'Transfert envoyé',
