  `email_body` = '<p>Votre plan d\'investissement <strong>{{plan_name}}</strong> est arrivé à échéance et a été clôturé avec succès.</p><p>Détails :</p><ul><li><strong>Numéro de transaction :</strong> {{trx}}</li><li><strong>Plan :</strong> {{plan_name}}</li><li><strong>Montant investi :</strong> {{invest_amount}}</li><li><strong>Retour total :</strong> {{total_return}}</li><li><strong>Date et heure :</strong> {{time}}</li><li><strong>Solde actuel :</strong> {{remain_balance}}</li></ul><p>Votre capital et les intérêts perçus ont été ajoutés à votre solde. Merci de votre confiance en {{site_name}}.</p>',
  `sms_body` = 'Votre investissement "{{plan_name}}" est terminé. Retour total : {{total_return}}. Solde : {{remain_balance}}.',
  `push_body` = 'Votre investissement « {{plan_name}} » est terminé. Retour total : {{total_return}}.'
WHERE `act` = 'INVESTMENT_COMPLETED';

UPDATE `notification_templates` SET
  `subject` = 'Votre capital investi vous a été restitué',
  `push_title` = 'Capital restitué',
  `email_body` = '<p>Nous avons le plaisir de vous informer que le capital investi dans <strong>{{plan_name}}</strong> vous a été restitué.</p><p>Détails :</p><ul><li><strong>Numéro de transaction :</strong> {{trx}}</li><li><strong>Plan :</strong> {{plan_name}}</li><li><strong>Capital restitué :</strong> {{capital_amount}}</li><li><strong>Date et heure :</strong> {{time}}</li><li><strong>Solde actuel :</strong> {{remain_balance}}</li></ul><p>Votre montant initial a été recrédité sur votre compte. Merci de votre confiance en {{site_name}}.</p>',
  `sms_body` = 'Votre capital investi dans "{{plan_name}}" ({{capital_amount}}) vous a été restitué. Solde : {{remain_balance}}.',
  `push_body` = 'Votre capital investi dans « {{plan_name}} » ({{capital_amount}}) vous a été restitué.'
WHERE `act` = 'INVESTMENT_CAPITAL_BACK';
